class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def build(values):
    if not values or values[0] is None:
        return None
    root = TreeNode(values[0])
    q = [root]
    i = 1
    while q and i < len(values):
        node = q.pop(0)
        if i < len(values) and values[i] is not None:
            node.left = TreeNode(values[i]); q.append(node.left)
        i += 1
        if i < len(values) and values[i] is not None:
            node.right = TreeNode(values[i]); q.append(node.right)
        i += 1
    return root

def kth_smallest(root, k):
    root = build(root)
    trail = []
    curr = root
    count = 0
    while trail or curr:
        while curr:
            trail.append(curr)
            curr = curr.left
        curr = trail.pop()
        count += 1
        if count == k:
            return curr.val
        curr = curr.right
    return -1
